def get_token():
    cid = os.getenv("CDSE_CLIENT_ID", "").strip()
    secret = os.getenv("CDSE_CLIENT_SECRET", "").strip()
    if not cid or not secret:
        raise RuntimeError("CDSE credentials are not loaded. Set CDSE_CLIENT_ID and CDSE_CLIENT_SECRET in the same runtime that runs Streamlit.")
    r = requests.post(TOKEN_URL, data={"grant_type":"client_credentials","client_id":cid,"client_secret":secret}, timeout=45)
    r.raise_for_status()
    return r.json()["access_token"]

def geocode_place(place):
    r = requests.get("https://nominatim.openstreetmap.org/search", params={"q":place,"format":"jsonv2","limit":1}, headers={"User-Agent":"AapdaSaarthi/1.0 disaster-assessment-student-project"}, timeout=30)
    r.raise_for_status()
    items = r.json()
    if not items:
        raise ValueError("Place not found. Try a city, district, landmark or more specific address.")
    x = items[0]
    return [float(x["lon"])-0.08, float(x["lat"])-0.08, float(x["lon"])+0.08, float(x["lat"])+0.08], x["display_name"]

def search_scenes(token, bbox, start_date, end_date, max_cloud=100):
    start = datetime.combine(start_date, datetime.min.time(), tzinfo=timezone.utc).isoformat().replace("+00:00","Z")
    end = datetime.combine(end_date, datetime.max.time(), tzinfo=timezone.utc).isoformat().replace("+00:00","Z")
    payload = {
    "collections": ["sentinel-1-grd"],
    "bbox": bbox,
    "datetime": f"{start}/{end}",
    "limit": 100
}
    r = requests.post(CATALOGUE_URL, headers={"Authorization":f"Bearer {token}","Content-Type":"application/json"}, json=payload, timeout=90)
    r.raise_for_status()
    features = r.json().get("features",[])
    rows=[]
    for f in features:
        p=f.get("properties",{})
        pol=p.get("sar:polarizations",[])
        if isinstance(pol,str): pol=[pol]
        rows.append({
            "id":f.get("id"),"datetime":p.get("datetime"),
            "orbit":p.get("sat:relative_orbit"),"direction":p.get("sat:orbit_state"),
            "mode":p.get("sar:instrument_mode"),"polarizations":pol,
            "platform":p.get("platform"),"bbox":f.get("bbox")
        })
        print("Total scenes found:", len(rows))
        print("Available polarizations:", [x for x in rows[:10]])
    return pd.DataFrame(rows)


def choose_pair(df, pre_date, post_date):
    if df.empty:
        return None

    d = df.copy()
    d["dt"] = pd.to_datetime(d["datetime"], utc=True)

    d = d[
        d["polarizations"].apply(
            lambda x: "VV" in x and "VH" in x
        )
    ]

    pre = d[d["dt"].dt.date <= pre_date].copy()
    post = d[d["dt"].dt.date >= post_date].copy()

    candidates = []

    for _, a in pre.iterrows():
        for _, b in post.iterrows():

            if (
                a["orbit"] != b["orbit"]
                or a["direction"] != b["direction"]
                or a["mode"] != b["mode"]
            ):
                continue

            gap = (b["dt"] - a["dt"]).total_seconds() / 86400

            if gap <= 0:
                continue

            score = (
                abs((a["dt"].date() - pre_date).days)
                + abs((b["dt"].date() - post_date).days)
            )

            candidates.append((score, gap, a, b))

    if not candidates:
        return None

    candidates.sort(key=lambda x: (x[0], x[1]))

    _, _, a, b = candidates[0]

    return a.to_dict(), b.to_dict()


def process_scene(token, bbox, scene):
    stamp=pd.Timestamp(scene["datetime"]).to_pydatetime()
    start=(stamp-timedelta(seconds=45)).astimezone(timezone.utc).isoformat().replace("+00:00","Z")
    end=(stamp+timedelta(seconds=45)).astimezone(timezone.utc).isoformat().replace("+00:00","Z")
    evalscript="""//VERSION=3
function setup(){return {input:[{bands:["VV","VH"],units:"LINEAR_POWER"}],output:{bands:2,sampleType:"FLOAT32"}};}
function evaluatePixel(s){return [s.VV,s.VH];}"""
    body={
        "input":{"bounds":{"bbox":bbox,"properties":{"crs":"http://www.opengis.net/def/crs/EPSG/0/4326"}},"data":[{"type":"sentinel-1-grd","dataFilter":{"timeRange":{"from":start,"to":end},"mosaickingOrder":"mostRecent"},"processing":{"orthorectify":True,"backCoeff":"GAMMA0_TERRAIN"}}]},
        "output":{"width":512,"height":512,"responses":[{"identifier":"default","format":{"type":"image/tiff"}}]},
        "evalscript":evalscript
    }
    r=requests.post(PROCESS_URL,headers={"Authorization":f"Bearer {token}","Content-Type":"application/json"},json=body,timeout=180)
    if r.status_code != 200:
     print("CDSE STATUS:", r.status_code)
     print("CDSE ERROR:", r.text)
     r.raise_for_status()
    return r.content

def read_tiff(blob):
    with MemoryFile(blob) as mem:
        with mem.open() as ds:
            arr=ds.read().astype("float32")
            profile=ds.profile.copy()
    return arr,profile

def process_arrays(pre, post, profile, threshold_vv, threshold_vh, min_pixels):
    valid=np.isfinite(pre).all(axis=0)&np.isfinite(post).all(axis=0)&(pre[0]>0)&(pre[1]>0)&(post[0]>0)&(post[1]>0)
    pre_db=10*np.log10(np.maximum(pre,1e-10))
    post_db=10*np.log10(np.maximum(post,1e-10))
    dvv=post_db[0]-pre_db[0]
    dvh=post_db[1]-pre_db[1]
    raw=valid&(dvv<=-abs(threshold_vv))&(dvh<=-abs(threshold_vh))
    labels,n=ndimage.label(raw,structure=np.ones((3,3),dtype=np.uint8))
    counts=np.bincount(labels.ravel())
    keep=np.where(counts>=int(min_pixels))[0]
    keep=keep[keep!=0]
    mask=np.isin(labels,keep)&valid
    return {"valid":valid,"pre_vv":pre_db[0],"post_vv":post_db[0],"pre_vh":pre_db[1],"post_vh":post_db[1],"dvv":dvv,"dvh":dvh,"raw":raw,"mask":mask,"labels":labels,"components":n,"retained":len(keep)}

def pixel_area_km2(mask, transform, crs):
    if not np.any(mask): return 0.0
    geod=Geod(ellps="WGS84")
    tr=None
    if crs and crs.to_epsg()!=4326:
        from pyproj import Transformer
        tr=Transformer.from_crs(crs,"EPSG:4326",always_xy=True)
    total=0.0
    rows=np.where(mask)[0]
    for r in np.unique(rows):
        count=int(np.sum(mask[int(r)]))
        x0,y0=transform*(0,int(r))
        x1,y1=transform*(1,int(r)+1)
        if tr:
            x0,y0=tr.transform(x0,y0)
            x1,y1=tr.transform(x1,y1)
        area,_=geod.polygon_area_perimeter([x0,x1,x1,x0],[y0,y0,y1,y1])
        total+=abs(area)*count
    return total/1e6

def png_overlay(array, valid, cmap="viridis", low=None, high=None, alpha=190):
    a=np.asarray(array,dtype=float)
    vals=a[valid&np.isfinite(a)]
    if vals.size==0: return None
    lo=float(np.nanpercentile(vals,2) if low is None else low)
    hi=float(np.nanpercentile(vals,98) if high is None else high)
    if hi<=lo: hi=lo+1
    norm=np.clip((a-lo)/(hi-lo),0,1)
    if cmap=="mask":
        rgba=np.zeros((*a.shape,4),dtype=np.uint8)
        rgba[a>0]=[255,91,91,alpha]
    else:
        import matplotlib
        cm=matplotlib.colormaps.get_cmap(cmap)
        rgba=(cm(norm)*255).astype(np.uint8)
        rgba[...,3]=np.where(valid,alpha,0).astype(np.uint8)
    im=Image.fromarray(rgba,"RGBA")
    buf=io.BytesIO(); im.save(buf,format="PNG")
    return buf.getvalue()

def add_overlay(map_obj, png, bounds, name):
    if png:
        import base64
        src="data:image/png;base64,"+base64.b64encode(png).decode()
        folium.raster_layers.ImageOverlay(src,bounds=bounds,opacity=0.78,name=name,interactive=True,cross_origin=False,zindex=5).add_to(map_obj)

def write_geotiff(path, array, profile, nodata=None):
    p=profile.copy()
    p.update(count=1,dtype="float32",compress="deflate",nodata=nodata)
    out=np.asarray(array,dtype="float32").copy()
    if nodata is not None:
        out[~np.isfinite(out)]=nodata
    with rasterio.open(path,"w",**p) as ds:
        ds.write(out,1)

def save_run(pre_blob,post_blob,pre,post,profile,result,bbox,pre_scene,post_scene,place_label,pre_target_date,post_target_date):
    stamp=datetime.now().strftime("%Y%m%d_%H%M%S")
    folder=RUN_ROOT/f"run_{stamp}"
    folder.mkdir(parents=True,exist_ok=True)
    (folder/"PRE_SAR.tif").write_bytes(pre_blob)
    (folder/"POST_SAR.tif").write_bytes(post_blob)
    proc=folder/"processed";proc.mkdir()
    for name,key in [("VV_change_db.tif","dvv"),("VH_change_db.tif","dvh")]:
        write_geotiff(proc/name,result[key],profile,-9999)
    write_geotiff(proc/"RuleB_candidate_mask.tif",result["mask"].astype(float),profile,255)
    write_geotiff(proc/"raw_candidate_mask.tif",result["raw"].astype(float),profile,255)
    meta={"bbox":bbox,"place":place_label,"pre_target_date":str(pre_target_date),"post_target_date":str(post_target_date),"pre_scene":pre_scene,"post_scene":post_scene,"created_utc":datetime.now(timezone.utc).isoformat()}
    (folder/"acquisition_metadata.json").write_text(json.dumps(meta,indent=2,default=str))
    return folder

def reference_metrics(candidate, reference, candidate_valid, reference_nodata=None):
    valid=np.asarray(candidate_valid,dtype=bool)&np.isfinite(candidate)&np.isfinite(reference)
    if reference_nodata is not None:
        if np.isnan(reference_nodata):
            valid &= ~np.isnan(reference)
        else:
            valid &= reference != reference_nodata
    values=np.unique(reference[valid])
    if not np.all(np.isin(values,[0,1])):
        raise ValueError("Reference mask must contain only binary 0/1 values after NoData is excluded.")
    c=np.asarray(candidate)[valid]>0
    r=np.asarray(reference)[valid]>0
    tp=int(np.sum(c&r));fp=int(np.sum(c&~r));fn=int(np.sum(~c&r));tn=int(np.sum(~c&~r))
    precision=tp/(tp+fp) if tp+fp else 0
    recall=tp/(tp+fn) if tp+fn else 0
    f1=2*precision*recall/(precision+recall) if precision+recall else 0
    iou=tp/(tp+fp+fn) if tp+fp+fn else 0
    return {"Evaluation pixels":int(valid.sum()),"TP":tp,"FP":fp,"TN":tn,"FN":fn,"Precision":precision,"Recall":recall,"F1":f1,"IoU":iou,"Accuracy":(tp+tn)/valid.sum() if valid.sum() else 0}


def restore_previous_assessment():
    roots=[Path("/content/AapdaSaarthi_Results"),Path("/content/AapdaSaarthi_Live_Test/Process_API_Downloads")]
    candidates=[]
    for root in roots:
        if root.exists():
            candidates.extend([x for x in root.glob("run_*") if (x/"PRE_SAR.tif").exists() and (x/"POST_SAR.tif").exists()])
    if not candidates:return None
    folder=max(candidates,key=lambda x:x.stat().st_mtime)
    try:
        with rasterio.open(folder/"PRE_SAR.tif") as ds:
            pre=ds.read().astype("float32");profile=ds.profile.copy()
        with rasterio.open(folder/"POST_SAR.tif") as ds:post=ds.read().astype("float32")
        result=process_arrays(pre,post,profile,2.5,2.0,8)
        mp=folder/"acquisition_metadata.json"
        if not mp.exists():mp=folder/"metadata.json"
        meta=json.loads(mp.read_text()) if mp.exists() else {}
        bbox=meta.get("bbox",[-0.45,39.35,-0.30,39.50])
        pre_scene=meta.get("pre_scene",{"datetime":"Previously retrieved"})
        post_scene=meta.get("post_scene",{"datetime":"Previously retrieved"})
        valid=int(result["valid"].sum());raw=int(result["raw"].sum());cand=int(result["mask"].sum())
        area=pixel_area_km2(result["mask"],profile["transform"],profile.get("crs"))
        summary={"AOI":meta.get("place","Restored previous assessment"),"PRE acquisition":pre_scene.get("datetime","Previously retrieved"),"POST acquisition":post_scene.get("datetime","Previously retrieved"),"Valid shared pixels":valid,"Raw change-detected pixels":raw,"Filtered candidate pixels":cand,"Candidate area km²":area,"Candidate regions":int(result["retained"]),"Affected share of valid pixels %":100*cand/valid if valid else 0,"Mean VV change dB":float(np.nanmean(result["dvv"][result["valid"]])) if valid else 0,"Mean VH change dB":float(np.nanmean(result["dvh"][result["valid"]])) if valid else 0}
        return {"result":result,"profile":profile,"summary":summary,"folder":str(folder),"bbox":bbox,"pre_scene":pre_scene,"post_scene":post_scene}
    except Exception as e:
        st.sidebar.warning(f"Previous run could not be restored: {e}")
        return None

