        diag=pd.DataFrame([{"Metric":"PRE/POST common valid pixels","Value":int(r["valid"].sum())},{"Metric":"Raw threshold candidate pixels","Value":int(r["raw"].sum())},{"Metric":"Filtered candidate pixels","Value":int(r["mask"].sum())},{"Metric":"Connected components before filtering","Value":int(r["components"])},{"Metric":"Retained components","Value":int(r["retained"])},{"Metric":"Mean VV change (dB)","Value":float(np.nanmean(r["dvv"][r["valid"]]))},{"Metric":"Mean VH change (dB)","Value":float(np.nanmean(r["dvh"][r["valid"]]))}])
        st.dataframe(diag,use_container_width=True)
        st.markdown("### Optional reference-mask validation")
        ref_file=st.file_uploader("Upload an independent binary reference GeoTIFF (same grid as candidate mask)",type=["tif","tiff"])
        if ref_file:
            try:
                with MemoryFile(ref_file.getvalue()) as mem:
                    with mem.open() as ds:
                        ref=ds.read(1)
                        ref_transform=ds.transform
                        ref_crs=ds.crs
                        ref_nodata=ds.nodata
                candidate_profile=assessment["profile"]
                same_transform=all(abs(a-b)<1e-9 for a,b in zip(tuple(ref_transform),tuple(candidate_profile["transform"])))
                same_crs=ref_crs==candidate_profile.get("crs")
                if ref.shape!=r["mask"].shape:
                    st.error("Reference raster dimensions differ. Reproject/resample it to the candidate raster grid before validation.")
                elif not same_transform or not same_crs:
                    st.error("Reference raster georeferencing does not match the candidate raster. Align its CRS and transform before validation.")
                else:
                    metrics=reference_metrics(r["mask"].astype(float),ref.astype(float),r["valid"],ref_nodata)
                    st.dataframe(pd.DataFrame([{"Metric":k,"Value":v} for k,v in metrics.items()]),use_container_width=True)
                    st.caption("NoData pixels are excluded. Scores are meaningful only when the uploaded binary reference is independent and correctly aligned.")
            except Exception as e: st.error(f"Reference validation failed: {e}")
        st.warning("Precision, recall, F1 and IoU are intentionally not fabricated. They are calculated only when an independent reference mask is supplied.")

